<script lang="ts">
  import {onMount} from 'svelte';
  import {invoke} from '@tauri-apps/api/core';
  type Feature={id:string;title:string;model:string|null;downloads:string[];modelBytes:number;ready:boolean;canInstall:boolean;message:string;activeVersion:string|null;requiresConsent:boolean;requiredStorageBytes:number};
  type Plan={supported:boolean;reason:string;hardware:{os:string;arch:string;totalRamBytes:number;freeRamBytes:number;physicalCores:number|null;avx2:boolean|null;nvidia:{index:number;computeMajor:number;computeMinor:number;totalVramBytes:number;freeVramBytes:number}[]};osVersion:string|null;freeStorageBytes:number;routing:{tier:string;downloadBytes:number;downloads:string[];warnings:string[]};features:Feature[]};
  const desktop='__TAURI_INTERNALS__' in window;
  let plan=$state<Plan|null>(null),checking=$state(false),error=$state('');
  let alive=true;
  const size=(bytes:number)=>bytes>=1024**3?`${(bytes/1024**3).toFixed(1)} GB`:`${Math.ceil(bytes/1024**2)} MB`;
  async function check(){if(!desktop||checking)return null;checking=true;error='';try{const next=await invoke<Plan>('get_setup_plan');if(alive)plan=next;return next;}catch{if(alive)error='Hardware could not be checked. Try again before downloading new tools.';return null;}finally{if(alive)checking=false;}}
  onMount(()=>{void check();const changed=()=>void check();window.addEventListener('studio-tools-changed',changed);return()=>{alive=false;window.removeEventListener('studio-tools-changed',changed);};});
</script>
<section class="card hardware-setup" aria-label="Automatic model setup">
  <div class="section-heading"><div><h2>Tools for this computer</h2><p>We choose compatible resources and take care of the setup.</p></div><button class="secondary" disabled={checking||!desktop} onclick={check}>{checking?'Checking…':'Check hardware again'}</button></div>
  {#if !desktop}<p class="hint">Open the desktop app to check your computer and prepare local voice tools.</p>
  {:else if !plan&&!error}<p role="status">Checking your computer…</p>
  {:else if plan}
    <div class="computer-match" role="status"><strong>{plan.hardware.os==='macos'&&['aarch64','arm64'].includes(plan.hardware.arch)?'Apple Silicon Mac':plan.hardware.os==='windows'?'Windows computer':'This computer'}</strong><span>{size(plan.hardware.totalRamBytes)} memory · {size(plan.freeStorageBytes)} available storage</span><p>{plan.reason}</p></div>
    {#if plan.routing.warnings.length}<div class="hardware-notes">{#each plan.routing.warnings as warning}<p>{warning}</p>{/each}</div>{/if}
    <ul class="matched-tools">{#each plan.features.filter(f=>['transcription','dictation','speech'].includes(f.id)) as feature}<li><div><strong>{feature.title}</strong><span class:ready={feature.ready}>{feature.ready?'Ready':!plan.supported?'Not supported':feature.canInstall?'Setup available':feature.id==='editing'?(feature.model?'Optional':'Unavailable'):'Not released yet'}</span></div><p>{feature.message}</p></li>{/each}</ul>
    {#if plan.features.some(f=>!['transcription','dictation','speech'].includes(f.id))}<details><summary>Optional tools</summary><ul class="matched-tools">{#each plan.features.filter(f=>!['transcription','dictation','speech'].includes(f.id)) as feature}<li><div><strong>{feature.title}</strong><span class:ready={feature.ready}>{feature.ready?'Ready':'Optional'}</span></div><p>{feature.message}</p></li>{/each}</ul></details>{/if}
    <details><summary>Hardware and model details</summary><dl><div><dt>System</dt><dd>{plan.hardware.os} {plan.osVersion??''} · {plan.hardware.arch}</dd></div><div><dt>Physical CPU cores</dt><dd>{plan.hardware.physicalCores??'Unknown'}</dd></div><div><dt>Free memory now</dt><dd>{size(plan.hardware.freeRamBytes)}</dd></div><div><dt>Model profile</dt><dd>{plan.routing.tier}</dd></div>{#each plan.hardware.nvidia as gpu}<div><dt>NVIDIA GPU {gpu.index}</dt><dd>Compute {gpu.computeMajor}.{gpu.computeMinor} · {size(gpu.totalVramBytes)} video memory</dd></div>{/each}</dl>
      <p>Recommendations use hardware capacity. Low free memory is a warning; installed tools are kept. Model files and compatible runtime packs are checked separately before use.</p>
      {#each plan.features.filter(f=>f.model) as feature}<div class="model-choice"><strong>{feature.title}</strong><span>Recommended: {feature.model} · {size(feature.modelBytes)} model files</span>{#if feature.requiredStorageBytes>0}<small>Additional setup space: {size(feature.requiredStorageBytes)}</small>{/if}{#if feature.activeVersion}<small>Installed version: {feature.activeVersion}</small>{/if}{#if feature.downloads.length>1}<small>Required components: {feature.downloads.join(', ')}</small>{/if}</div>{/each}
      <p>The everyday model set contains {size(plan.routing.downloadBytes)} of distinct model files before cache reuse. Runtime downloads and temporary install space are additional. Editing stays a separate, optional download.</p>
    </details>
  {/if}
  {#if error}<p class="setup-error" role="alert">{error}</p>{/if}
</section>
<style>
 .hardware-setup .section-heading{justify-content:space-between;gap:14px}.hardware-setup .section-heading button{font-size:11px;padding:8px 12px;flex:none}.hardware-setup p{font-size:12px;color:var(--studio-muted);line-height:1.7}.computer-match{margin-top:20px;padding:15px;border:1px solid var(--studio-border);border-radius:12px}.computer-match strong,.computer-match span{display:block}.computer-match strong{font-size:14px}.computer-match span{font-size:11px;color:var(--studio-muted);margin-top:6px}.computer-match p{margin-bottom:0}.matched-tools{padding:0;margin:18px 0;list-style:none}.matched-tools li{padding:12px 0;border-bottom:1px solid var(--studio-divider)}.matched-tools li>div{display:flex;align-items:center;justify-content:space-between;gap:12px}.matched-tools strong{font-size:12px}.matched-tools span{font-size:10px;color:var(--studio-gold)}.matched-tools span.ready{color:var(--studio-accent)}.matched-tools p{font-size:11px;margin:5px 0 0}.hardware-notes{border-left:2px solid var(--studio-gold);padding-left:12px}.hardware-notes p{font-size:11px}details{margin-top:18px;font-size:12px}summary{cursor:pointer;color:var(--studio-muted);padding:8px 0}dl div{font-size:11px;gap:14px}dd{max-width:65%;overflow-wrap:anywhere}.model-choice{display:flex;flex-direction:column;gap:6px;padding:12px 0;border-top:1px solid var(--studio-divider);font-size:12px}.model-choice span,.model-choice small{font-size:11px;color:var(--studio-muted);overflow-wrap:anywhere}.setup-error{color:var(--studio-tone-ffb2be)!important}summary:focus-visible{outline:2px solid var(--studio-focus);outline-offset:3px}@media(max-width:700px){.hardware-setup .section-heading{flex-wrap:wrap}}
</style>
